d-track{width:180px;height:2px;background:#34312b;margin:4px}.load-track i{display:block;width:60%;height:100%;background:var(--gold);animation:load 1.15s ease-in-out infinite alternate}@keyframes load{from{width:8%}to{width:100%}.topbar{height:88px;padding:25px 4.4%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.09)}.brand{display:flex;gap:13px;align-items:center}.brand-mark{width:38px;height:38px;font-size:17px}.brand-name{font:800 20px 'Barlow Condensed';letter-spacing:.05em}.brand-name b{color:var(--gold)}.brand small{display:block;color:#a49c8d;letter-spacing:.19em;font-size:8px;margin-top:3px}.top-right{display:flex;align-items:center;gap:26px}.edition,.platform-note,.menu-footer,.main-character-label,.step-label,.eyebrow,.hud-caption,.round-label,.round-rule,.selection-hint,.detail-kicker,.arena-note,.arena-tag{font-size:9px;letter-spacing:.16em;font-weight:700;color:#b9b1a3}.icon-btn{background:transparent;border:1px solid var(--line);border-radius:2px;padding:10px 13px;font-size:15px}.icon-btn span{font-size:9px;letter-spacing:.1em;margin-left:6px}.hero-copy{position:absolute;left:11.2%;top:24%;z-index:1}.eyebrow{display:flex;align-items:center;gap:10px;color:var(--gold)}.eyebrow i{width:18px;height:1px;background:var(--gold)}h1,h2,p{margin:0}h1{font:900 clamp(76px,10.4vw,145px)/.79 'Barlow Condensed';letter-spacing:-.035em;margin:24px 0 22px;text-shadow:0 6px 25px rgba(0,0,0,.4)}h1 em,h2 em{color:var(--gold);font-style:normal} .hero-copy p{font-size:14px;line-height:1.75;color:#c5beb2}.hero-actions{display:flex;gap:12px;margin-top:28px}.primary-btn,.secondary-btn{border:0;min-height:50px;padding:0 24px;font:800 12px 'Barlow Condensed';letter-spacing:.11em;background:var(--gold);color:#171611;box-shadow:0 8px 28px rgba(0,0,0,.2);transition:.2s}.primary-btn:hover{background:#f0c86e;transform:translateY(-2px)}.primary-btn span{font-size:18px;margin-left:27px}.secondary-btn{background:rgba(17,18,20,.62);